/**
 * Store interfaces — the persistence contract.
 *
 * Two implementations exist:
 *  - `src/storage/forge/`  → Forge SQL (runtime, spec §18)
 *  - `src/storage/memory/` → in-memory (tests + simulation console)
 *
 * Services only ever depend on these interfaces. No @forge/* import below
 * this line. All ids are opaque strings generated by the stores (uuid-ish).
 * All timestamps are ISO-8601 strings.
 */

import type {
  ActorSession,
  Collision,
  CollisionDraft,
  EventInput,
  EventRecord,
  FootprintCoverage,
  FootprintEntry,
  FootprintEntryInput,
  FootprintSource,
  FootprintPrediction,
  HookToken,
  Notice,
  NoticeView,
  PathKind,
  PriorityRules,
  RealConflict,
  RepoRecord,
  Reservation,
  Worksite,
  Zone,
} from "../core/types";

export interface RepoStore {
  upsert(repo: RepoRecord): Promise<RepoRecord>;
  findById(id: string): Promise<RepoRecord | undefined>;
  findBySlug(projectId: string, slug: string): Promise<RepoRecord | undefined>;
  listByProject(projectId: string): Promise<RepoRecord[]>;
  /** Find-or-create by (projectId, slug); applies default zone catalog on create. */
  ensure(projectId: string, slug: string, defaultBranch?: string): Promise<RepoRecord>;
}

export interface ZoneStore {
  upsert(zone: Zone): Promise<Zone>;
  findById(id: string): Promise<Zone | undefined>;
  listByRepo(repoId: string): Promise<Zone[]>;
  remove(id: string): Promise<boolean>;
  /** Idempotently apply the default catalog (spec §6) to a repo. */
  seedDefaults(repoId: string): Promise<Zone[]>;
}

export interface SessionStore {
  /** Upsert by (accountId, client, sessionRef, agentRef?); refreshes lastSeen. */
  touch(session: Omit<ActorSession, "id" | "firstSeen" | "lastSeen"> & { at: string; id?: string }): Promise<ActorSession>;
  findById(id: string): Promise<ActorSession | undefined>;
  findByRef(accountId: string, sessionRef: string, agentRef?: string): Promise<ActorSession | undefined>;
  listByAccount(accountId: string): Promise<ActorSession[]>;
}

export interface WorksiteStore {
  create(w: Omit<Worksite, "id"> & { id?: string }): Promise<Worksite>;
  update(id: string, patch: Partial<Worksite>): Promise<Worksite | undefined>;
  findById(id: string): Promise<Worksite | undefined>;
  /** The open-ish worksite of a session (agents) — most recent non-closed. */
  findBySession(sessionId: string): Promise<Worksite | undefined>;
  /** Open-ish worksites for a ticket in a repo (optionally one session). */
  findByIssue(issueKey: string, repoId?: string, sessionId?: string): Promise<Worksite[]>;
  /** All non-closed worksites of a repo. */
  listOpenByRepo(repoId: string): Promise<Worksite[]>;
  listByAccount(accountId: string): Promise<Worksite[]>;
  /** Non-closed worksites idle since `before` (ISO). */
  listIdleBefore(before: string): Promise<Worksite[]>;
  /** Dormant worksites dormant since before `before` (for auto-close). */
  listDormantBefore(before: string): Promise<Worksite[]>;
  /** Closed worksites with outcome "merged" (prediction accuracy, spec §13). */
  listMerged(repoId?: string, since?: string): Promise<Worksite[]>;
}

export interface FootprintStore {
  /** Add or refresh entries (same worksiteId+path → update lastAt, widen source/mode). */
  add(entries: FootprintEntryInput[]): Promise<FootprintEntry[]>;
  listByWorksite(worksiteId: string): Promise<FootprintEntry[]>;
  /**
   * Entries whose path equals, contains, or is contained by `path`
   * (patterns matched as globs), limited to `repoId` — served by the
   * (repo_id, path) index: exact path + each parent dir for a file;
   * also entries starting with `path` for a dir (spec §18).
   * Callers filter out closed worksites via WorksiteStore.
   */
  findOverlapping(repoId: string, path: string, kind?: PathKind): Promise<FootprintEntry[]>;
  removeByWorksite(worksiteId: string, source?: FootprintSource): Promise<number>;
  coverage(worksiteId: string): Promise<FootprintCoverage>;
}

export interface CollisionStore {
  /** Upsert; unique per (repoId, worksiteA<worksiteB, zoneId). Keeps first detectedAt. */
  upsert(draft: CollisionDraft): Promise<Collision>;
  findById(id: string): Promise<Collision | undefined>;
  listByRepo(repoId: string, activeOnly?: boolean): Promise<Collision[]>;
  listByWorksite(worksiteId: string, activeOnly?: boolean): Promise<Collision[]>;
  listByIds(ids: string[]): Promise<Collision[]>;
  resolve(
    id: string,
    resolution: Collision["resolution"],
    resolvedBy: string,
    reason?: string,
  ): Promise<Collision | undefined>;
  countByPhase(repoId?: string, since?: string): Promise<Record<string, number>>;
}

export interface ReservationStore {
  create(r: Omit<Reservation, "id"> & { id?: string }): Promise<Reservation>;
  findById(id: string): Promise<Reservation | undefined>;
  /** Active (not released, not expired) at `now`. */
  listActive(repoId: string, now: string): Promise<Reservation[]>;
  /** Active reservations whose patterns overlap any of `paths`. */
  findActiveOverlapping(repoId: string, paths: string[], now: string): Promise<Reservation[]>;
  listByWorksite(worksiteId: string, now: string): Promise<Reservation[]>;
  release(id: string, now: string): Promise<boolean>;
  /** Release everything expired; returns what was released. */
  releaseExpired(now: string): Promise<Reservation[]>;
}

export interface NoticeStore {
  /** Post a notice and register its recipients (computed by the service). */
  post(notice: Omit<Notice, "id"> & { id?: string }, recipientWorksiteIds: string[]): Promise<Notice>;
  listByWorksite(worksiteId: string): Promise<Notice[]>;
  /** Undelivered notices for these worksites, oldest first. */
  pendingFor(worksiteIds: string[]): Promise<NoticeView[]>;
  markDelivered(noticeId: string, worksiteId: string, at: string): Promise<void>;
}

export interface PredictionStore {
  save(p: FootprintPrediction): Promise<FootprintPrediction>;
  findByIssue(issueKey: string, repoId?: string): Promise<FootprintPrediction[]>;
  removeByIssue(issueKey: string): Promise<number>;
}

export interface ConflictStore {
  report(c: Omit<RealConflict, "id"> & { id?: string }): Promise<RealConflict>;
  list(repoId?: string, since?: string): Promise<RealConflict[]>;
}

export interface TokenStore {
  create(t: Omit<HookToken, "createdAt"> & { createdAt?: string }): Promise<HookToken>;
  findByHash(tokenHash: string): Promise<HookToken | undefined>;
  touchLastUsed(tokenHash: string, at: string): Promise<void>;
  listByAccount(accountId: string): Promise<HookToken[]>;
  revoke(tokenHash: string): Promise<boolean>;
}

export interface EventStore {
  append(e: EventInput): Promise<EventRecord>;
  listByWorksite(worksiteId: string, limit?: number): Promise<EventRecord[]>;
  recent(limit?: number): Promise<EventRecord[]>;
}

export interface RulesStore {
  /** Returns stored rules or DEFAULT_PRIORITY_RULES for the project. */
  get(projectId: string): Promise<PriorityRules>;
  set(rules: PriorityRules): Promise<PriorityRules>;
}

/** The full persistence bundle injected into services via Ctx. */
export interface Stores {
  repos: RepoStore;
  zones: ZoneStore;
  sessions: SessionStore;
  worksites: WorksiteStore;
  footprints: FootprintStore;
  collisions: CollisionStore;
  reservations: ReservationStore;
  notices: NoticeStore;
  predictions: PredictionStore;
  conflicts: ConflictStore;
  tokens: TokenStore;
  events: EventStore;
  rules: RulesStore;
}
